def price_file(seed, n):
    """A seeded file of n trading days from 1 September 2025, newest first, with one day sent twice."""
    x = seed
    def u():
        nonlocal x
        x = (6364136223846793005 * x + 1442695040888963407) % 2 ** 64
        return (x >> 11) / 2 ** 53
    close, rows = 60.0, []
    for d in pd.bdate_range("2025-09-01", periods=n):
        close = round(close * (0.975 + 0.05 * u()), 2)
        rows.append(f"{d.date()},{close:.2f}")
    rows = rows[::-1]
    rows.append(rows[int(n * u())])
    return "date,close\n" + "\n".join(rows) + "\n"


def _iso(x):
    """A point's date on a matplotlib date axis, as an ISO string."""
    if isinstance(x, (int, float, np.integer, np.floating)):
        return mdates.num2date(float(x)).date().isoformat()
    return pd.Timestamp(x).date().isoformat()


def _points(ax, nd=6):
    """The finite points of the longest line on ax, as [ISO date, y rounded to nd places]."""
    line = max(ax.get_lines(), key=lambda ln: len(ln.get_xdata()))
    xs, ys = line.get_xdata(orig=False), np.asarray(line.get_ydata(), dtype=float)
    return [[_iso(a), round(float(b), nd)] for a, b in zip(xs, ys) if np.isfinite(b)]


def _arrow(ax):
    """The annotation on ax whose text starts Max drawdown, as [text, ISO date, y]."""
    for t in ax.texts:
        if t.get_text().startswith("Max drawdown"):
            return [t.get_text(), _iso(t.xy[0]), round(float(t.xy[1]), 6)]
    raise LookupError("no annotation starting 'Max drawdown' on the bottom panel")


def _png_dpi(p):
    """The dots per inch written in a PNG file's pHYs chunk."""
    b = open(p, "rb").read()
    i = b.find(b"pHYs")
    return round(struct.unpack(">I", b[i + 4:i + 8])[0] * 0.0254)

